// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type PlaneFlybyProps = Record<string, any>;

const PlaneFlyby: React.FC<PlaneFlybyProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 8,
  mainText = "100k",
  subText = "users",
  textColor = "#ffffff",
  planeColor = "#ffffff",
  trailColor = "#ffffff",
  trailWidth = 6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Logic to prevent parser errors
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Timing Configuration
  const textEntranceStart = 15;
  const subTextEntranceStart = 30;
  const flyStart = 75;
  const flyEnd = 165;

  // Text Animations
  const mainTextScale = spring({
    frame: Math.max(0, frame - textEntranceStart),
    fps,
    config: { damping: 14, mass: 1.5 },
  });
  
  const mainTextOpacity = interpolate(
    frame,
    [textEntranceStart, textEntranceStart + 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const subTextOpacity = interpolate(
    frame,
    [subTextEntranceStart, subTextEntranceStart + 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const subTextY = interpolate(
    frame,
    [subTextEntranceStart, subTextEntranceStart + 20],
    [30 * s, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.quad),
    }
  );

  // Path Math (Cubic Bezier sweeping across the screen)
  const x0 = width * 0.15;
  const y0 = height * 0.95;
  
  const x1 = width * 0.45;
  const y1 = height * 0.9;
  
  const x2 = width * 0.75;
  const y2 = height * 0.7;
  
  const x3 = width * 1.15;
  const y3 = height * 0.2;

  // Flight progress
  const t = interpolate(frame, [flyStart, flyEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.sin),
  });

  // De Casteljau truncated path calculation
  const L = (a: number, b: number, tVal: number) => a + (b - a) * tVal;
  
  const ax = L(x0, x1, t);
  const ay = L(y0, y1, t);
  const bx = L(x1, x2, t);
  const by = L(y1, y2, t);
  const cx = L(x2, x3, t);
  const cy = L(y2, y3, t);

  const dx = L(ax, bx, t);
  const dy = L(ay, by, t);
  const ex = L(bx, cx, t);
  const ey = L(by, cy, t);

  const tipX = L(dx, ex, t);
  const tipY = L(dy, ey, t);

  const partialD = `M ${x0} ${y0} C ${ax} ${ay}, ${dx} ${dy}, ${tipX} ${tipY}`;

  // Derivative computation for stable tangent angle (avoids atan2(0,0) at t=0)
  const mt = 1 - t;
  const tanX =
    3 * mt * mt * (x1 - x0) +
    6 * mt * t * (x2 - x1) +
    3 * t * t * (x3 - x2);
  const tanY =
    3 * mt * mt * (y1 - y0) +
    6 * mt * t * (y2 - y1) +
    3 * t * t * (y3 - y2);
  const angle = Math.atan2(tanY, tanX) * (180 / Math.PI);

  // Plane visibility (fully hidden before entrance)
  const planeOpacity = interpolate(
    frame,
    [flyStart, flyStart + 5],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        overflow: "hidden",
      }}
    >
      {/* Typography Layer */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          height: "100%",
          zIndex: 1,
        }}
      >
        <div
          style={{
            fontSize: 280 * s,
            fontWeight: 900,
            color: textColor,
            lineHeight: 0.9,
            letterSpacing: -12 * s,
            opacity: mainTextOpacity,
            transform: `scale(${mainTextScale})`,
            transition: "none",
          }}
        >
          {mainText}
        </div>
        <div
          style={{
            fontSize: 96 * s,
            fontWeight: 700,
            color: textColor,
            lineHeight: 1,
            letterSpacing: -3 * s,
            marginTop: 10 * s,
            opacity: subTextOpacity,
            transform: `translateY(${subTextY}px)`,
            transition: "none",
          }}
        >
          {subText}
        </div>
      </div>

      {/* Animation Graphics Layer */}
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          zIndex: 2,
          pointerEvents: "none",
          opacity: planeOpacity,
          transition: "none",
        }}
      >
        {/* Contrail Path */}
        <path
          d={partialD}
          fill="none"
          stroke={trailColor}
          strokeWidth={trailWidth * s}
          strokeLinecap="round"
          style={{ transition: "none" }}
        />

        {/* Plane Tip Rider */}
        <g
          style={{
            transform: `translate(${tipX}px, ${tipY}px) rotate(${angle + 90}deg)`,
            transformOrigin: "0 0",
            transition: "none",
          }}
        >
          {/* Classic Commercial Jet SVG (Centered on 0,0) */}
          <path
            d="M0,-10 L2,-5 L10,-2 L10,0 L2,-1 L2,6 L6,9 L6,11 L0,9 L-6,11 L-6,9 L-2,6 L-2,-1 L-10,0 L-10,-2 L-2,-5 Z"
            fill={planeColor}
            transform={`scale(${3.5 * s})`}
            style={{ transition: "none" }}
          />
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default PlaneFlyby;